  'guide.students.why': 'लोगों को पूछताछ से नामांकन तक ले जाएँ। बच्चों के लिए माता-पिता या अभिभावक सहमति देते हैं।',
  'guide.classes.why': 'आज और सप्ताह एक नज़र में देखें, उपस्थिति लें और मेक-अप व रद्द कक्षाएँ दिखाई देती रखें।',
  'guide.tax.why': 'वसूला और चुकाया गया कर जानें, अपने कर नियमों और इनवॉइस पर कर विवरण के साथ।',
  'guide.revenue.why': 'तय करें कि कोचों के साथ पैसा कैसे बँटेगा और साझा खर्च प्रोग्रामों में कैसे बाँटे जाएँगे।',
  'guide.reports.why': 'कार्यकारी होम पर परिणाम, रिटेंशन, वित्तीय स्थिति और साझेदार देखें, और जो चाहिए उसे एक्सपोर्ट करें।',
