  'arp.scope.academy': 'अकादमी',
  'arp.aud.progress': 'अकादमी के मालिक और एडमिन, खिलाड़ी के कोच, खिलाड़ी और सत्यापित अभिभावक पढ़ सकते हैं। वित्त, चिकित्सा या कल्याण नोट, तथा कोच और स्टाफ़ की निजी प्रतिक्रिया कभी शामिल नहीं होती।',
  'arp.aud.term': 'विकास रिपोर्ट के ही पाठक। सत्र की उपस्थिति और साझा होने पर स्कूल बैंड जुड़ता है। स्कूल के ग्रेड कभी नहीं छपते।',
  'arp.aud.management': 'केवल अकादमी के मालिक और एडमिन पढ़ सकते हैं। 3 से कम के समूह संख्या के रूप में नहीं छपते। कानूनी, चिकित्सा या कोच का निजी ब्योरा नहीं।',
  'arp.aud.finance': 'केवल अकादमी के मालिक, एडमिन और वित्त पढ़ सकते हैं। प्रबंधन लेखा, वैधानिक या अंकेक्षित नहीं। कोचिंग या चिकित्सा डेटा नहीं।',
  'arp.aud.campus': 'केवल अकादमी के मालिक और एडमिन पढ़ सकते हैं। एक कैंपस: लोग, संचालन, स्टाफ़, वित्त। 3 से कम के समूह संख्या के रूप में नहीं छपते।',
  'arp.basis.progress': 'खिलाड़ी के लिए सुरक्षित प्रगति दृश्य: कोच के मूल्यांकन, अकादमी उपस्थिति और स्वीकृत आधिकारिक परिणाम अलग-अलग।',
  'arp.basis.term': 'सत्र की प्रगति, सत्र की उपस्थिति और साझा होने पर स्कूल बैंड। कुछ भी एक स्कोर में नहीं मिलाया जाता।',
  'arp.basis.management': 'एक्ज़ीक्यूटिव होम के उन्हीं आँकड़ों से प्रबंधन दृश्य। वैधानिक लेखा नहीं।',
