  'acc.mine_empty_sub': 'जब कोई अकादमी आपको निरीक्षक नामित करेगी, ऑडिट यहाँ दिखेगा।',
  'guide.accreditation.title': 'मान्यता और ऑडिट प्रबंधित करें',
  'guide.accreditation.why': 'आपकी अकादमी के पास जो भी बाहरी मान्यता, लाइसेंस और गुणवत्ता चिह्न हैं, उन्हें ट्रैक करें, हर एक का साक्ष्य उन रिकॉर्ड से लिंक रखें जो आप पहले से सँभालते हैं, और ऐसे निष्कर्षों व सुधारात्मक कार्रवाइयों के साथ ऑडिट चलाएँ जिन्हें चुपचाप बदला नहीं जा सकता।',
  'guide.accreditation.s1': 'अकादमी खोलें, फिर मान्यता, और फ्रेमवर्क जोड़ने के लिए कॉन्फ़िगर करें पर टैप करें: मान्यता देने वाली संस्था, प्रकार, स्तर, ज़िम्मेदार व्यक्ति, नवीनीकरण चक्र और याद दिलाने का समय।',
  'guide.accreditation.s2': 'फ्रेमवर्क खोलें, साक्ष्य चुनें, उसकी आवश्यकताएँ जोड़ें, फिर कोच की योग्यताएँ और अनुपालन रिकॉर्ड लिंक करें। कुछ भी कॉपी नहीं होता, और वैधता लाइव पढ़ी जाती है।',
  'guide.accreditation.s3': 'ऑडिट निर्धारित करें पर टैप करें, प्रकार, तिथि और जाँचने के क्षेत्र चुनें, और चाहें तो निरीक्षक नामित करें, जिन्हें केवल वही ऑडिट दिखेगा।',
  'guide.accreditation.s4': 'हर निष्कर्ष को उसकी गंभीरता और सुधारात्मक कार्रवाइयों के साथ दर्ज करें, हर कार्रवाई को ज़िम्मेदार व्यक्ति और देय तिथि दें, और काम पूरा होने पर उन्हें पूर्ण चिह्नित करें।',
  'guide.accreditation.s5': 'हर उच्च और मध्यम निष्कर्ष सुलझने पर पुनः प्रस्तुत करें, फिर निरीक्षक का निर्णय दर्ज करें। हर चरण एक लॉक इतिहास में सुरक्षित रहता है।',
