  'inc.lvl_secure': 'सुदृढ़',
  'inc.lvl_exceeding': 'अपेक्षा से आगे',
  'guide.inclusion.title': 'समावेशी और अनुकूलित कार्यक्रम चलाएँ',
  'guide.inclusion.why': 'दिव्यांग और पैरा खिलाड़ी बिना निदान बताए आपके कार्यक्रमों में शामिल होकर आगे बढ़ सकें: तय करें कि कार्यक्रम क्या प्रदान करता है, जाँचें कि हर अनुकूलित सत्र तैयार है, और खिलाड़ी केवल अपनी चुनी हुई व्यावहारिक ज़रूरतें साझा करें।',
  'guide.inclusion.s1': 'अकादमी खोलें, फिर समावेशन, फिर कार्यक्रम सेटअप, कोई कार्यक्रम चुनें और तय करें कि कौन शामिल हो सकता है, खेल अनुकूलन टेम्पलेट, दिए जाने वाले समायोजन, स्थल की सुविधाएँ और ज़रूरी सहायक अनुपात।',
  'guide.inclusion.s2': 'स्थल प्रबंधकों से कहें कि वे हर स्थल की पहुँच सुविधाएँ (लिफ़्ट, बिना सीढ़ी का रास्ता, सुगम चेंजिंग रूम, पूल हॉइस्ट) दर्ज करें ताकि सत्रों को उनसे मिलाकर जाँचा जा सके।',
  'guide.inclusion.s3': 'खिलाड़ी, या युवा का सत्यापित अभिभावक, मेरी अकादमी, फिर सुविधाएँ खोलकर केवल वही साझा करते हैं जो स्टाफ़ को चाहिए, किसके साथ और कब तक। वे इसे किसी भी क्षण वापस ले सकते हैं।',
  'guide.inclusion.s4': 'समावेशन, फिर सत्र तैयारी खोलें, कोई सत्र चुनें और हर कमी दूर करें: स्थल, सहायक व्यक्ति, ड्यूटी कवर और मुख्य कोच की योग्यता। कोच और स्थल स्टाफ़ केवल वही देखते हैं जो उनके साथ साझा किया गया, और हर बार देखना खिलाड़ी के लिए दर्ज होता है।',
  'guide.inclusion.s5': 'वर्णनात्मक स्तरों के साथ अनुकूलित, कोच-संचालित मूल्यांकन दर्ज करें, कभी एकल स्कोर नहीं, और दूसरे मूल्यांकनकर्ता से हस्ताक्षर करवाएँ। निदेशक अवलोकन में केवल संख्याएँ देखते हैं।',


